# Prepares the cross build of Mozc for Haiku/RenkuOS.
#
# Bazel cannot target Haiku, so the host build is used as the source of
# truth instead: for every group of targets this script reads the compile
# actions of a host (Linux) build from `bazel aquery`, and writes
#
#   <out>/sources.mk   which sources each group needs, and per file defines
#   <out>/gen/         files generated by the host build (protobuf code, the
#                      embedded dictionary, version header ...); they do not
#                      depend on the target platform
#   <out>/third_party/ abseil-cpp and protobuf, copied from the Bazel
#                      external repositories
#
# Usage:
#   gen_sources.py --bazel_bin=... --external=... --out=... \
#       GROUP=aquery.json [GROUP=aquery.json ...]

import argparse
import json
import os
import re
import shutil
import sys

# Defines that only make sense for the host build, or that the Haiku build
# sets differently.
DROPPED_DEFINE_PREFIXES = (
    '-D__DATE__',
    '-D__TIMESTAMP__',
    '-D__TIME__',
    '-DMOZC_DOCUMENT_DIR',
    '-DMOZC_SERVER_DIR',
    '-DMOZC_BROWSER_COMMAND',
    '-DNOMINMAX',
)

# Third party code is copied with these subdirectories.
THIRD_PARTY = {
    'abseil-cpp+': ['absl'],
    'protobuf+': ['src', 'third_party/utf8_range'],
}


def classify(path):
  """Returns (root variable, path relative to it) for a source file."""
  m = re.match(r'bazel-out/[^/]+/bin/external/protobuf\+/src/google/protobuf/'
               r'_virtual_imports/[^/]+/(google/protobuf/.*)', path)
  if m:
    return 'GEN', m.group(1)
  m = re.match(r'bazel-out/[^/]+/bin/(.*)', path)
  if m:
    return 'GEN', m.group(1)
  m = re.match(r'external/abseil-cpp\+/(.*)', path)
  if m:
    return 'ABSL', m.group(1)
  m = re.match(r'external/protobuf\+/(.*)', path)
  if m:
    return 'PROTOBUF', m.group(1)
  m = re.match(r'external/zlib\+/', path)
  if m:
    return None, None  # The system zlib is used.
  return 'MOZC', path


def read_actions(aquery_json):
  with open(aquery_json, encoding='utf-8') as f:
    data = json.load(f)
  for action in data.get('actions', []):
    args = action['arguments']
    if '-c' not in args or '-o' not in args:
      continue  # Header parsing.
    output = args[args.index('-o') + 1]
    if '-exec' in output.split('/')[1]:
      continue  # Built for the host to generate data.
    source = args[args.index('-c') + 1]
    defines = [a for a in args if a.startswith('-D')
               and not a.startswith(DROPPED_DEFINE_PREFIXES)]
    yield source, defines


def make_var(name):
  return re.sub(r'[^A-Za-z0-9_]', '_', name)


def main():
  parser = argparse.ArgumentParser()
  parser.add_argument('--bazel_bin', required=True)
  parser.add_argument('--external', required=True)
  parser.add_argument('--out', required=True)
  parser.add_argument('groups', nargs='+')
  args = parser.parse_args()

  sources = {}  # (root, path) -> defines
  groups = {}
  for group in args.groups:
    name, aquery_json = group.split('=', 1)
    members = []
    for source, defines in read_actions(aquery_json):
      root, path = classify(source)
      if root is None:
        continue
      key = (root, path)
      if key in sources and sources[key] != defines:
        sys.exit('conflicting defines for %s: %s vs %s'
                 % (path, sources[key], defines))
      sources[key] = defines
      if key not in members:
        members.append(key)
    groups[name] = members

  gen_dir = os.path.join(args.out, 'gen')
  shutil.rmtree(gen_dir, ignore_errors=True)
  # Generated sources and the headers next to them.
  for dirpath, _, filenames in os.walk(args.bazel_bin, followlinks=False):
    rel_dir = os.path.relpath(dirpath, args.bazel_bin)
    if rel_dir.startswith(('external', '_')) or '/_objs' in rel_dir \
        or rel_dir.startswith('_objs'):
      continue
    for filename in filenames:
      if not filename.endswith(('.pb.h', '.pb.cc', '.inc', '_def.h')):
        continue
      src = os.path.join(dirpath, filename)
      dst = os.path.join(gen_dir, rel_dir, filename)
      os.makedirs(os.path.dirname(dst), exist_ok=True)
      shutil.copyfile(src, dst)
  # Well known types of protobuf.
  wkt_root = os.path.join(args.bazel_bin, 'external', 'protobuf+', 'src',
                          'google', 'protobuf', '_virtual_imports')
  for dirpath, _, filenames in os.walk(wkt_root):
    for filename in filenames:
      if filename.endswith(('.pb.h', '.pb.cc')):
        dst = os.path.join(gen_dir, 'google', 'protobuf', filename)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.copyfile(os.path.join(dirpath, filename), dst)

  for repo, subdirs in THIRD_PARTY.items():
    dst_root = os.path.join(args.out, 'third_party', repo.rstrip('+'))
    shutil.rmtree(dst_root, ignore_errors=True)
    for subdir in subdirs:
      shutil.copytree(os.path.join(args.external, repo, subdir),
                      os.path.join(dst_root, subdir), symlinks=False)

  roots = {'MOZC': '$(MOZC_SRC)', 'GEN': '$(GEN_DIR)',
           'ABSL': '$(ABSL_DIR)', 'PROTOBUF': '$(PROTOBUF_DIR)'}

  def object_of(root, path):
    return '$(OBJ_DIR)/%s/%s.o' % (root.lower(), os.path.splitext(path)[0])

  with open(os.path.join(args.out, 'sources.mk'), 'w', encoding='utf-8') as f:
    f.write('# Generated by gen_sources.py. Do not edit.\n\n')
    for name, members in groups.items():
      f.write('%s_OBJECTS := \\\n' % name)
      for root, path in members:
        f.write('\t%s \\\n' % object_of(root, path))
      f.write('\n')
    for (root, path), defines in sorted(sources.items()):
      # Mozc's own code is built with warnings, the rest without.
      compile_var = 'COMPILE_MOZC' if root in ('MOZC',) else 'COMPILE_THIRD_PARTY'
      obj = object_of(root, path)
      f.write('%s: %s/%s\n' % (obj, roots[root], path))
      f.write('\t$(call %s,%s)\n\n' % (compile_var, ' '.join(defines)))


if __name__ == '__main__':
  main()
